while True:
    resp = apis.phone.search_contacts(access_token=phone_token, relationship='friend', page_index=page_index, page_limit=20)
    contacts = resp.get('contacts', [])
    for c in contacts:
        if c.get('email'):
            phone_friend_emails.append(c['email'])
    if len(contacts) < 20:
        break
    page_index += 1

