# Fetch all playlists to see their songs
all_playlist_songs = {}
for pid in playlist_ids:
    pl_data = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    print(f"Playlist {pid}: {pl_data['title']} - {len(pl_data['songs'])} songs")
    all_playlist_songs[pid] = pl_data['songs']

# Print all songs from all playlists with their IDs and titles
for pid, songs in all_playlist_songs.items():
    print(f"\nPlaylist {pid}:")
    for song in songs:
        print(f"  Song ID: {song['id']}, Title: {song['title']}")

