steps.code:
# Search for all archived songs and collect their song IDs
archived_song_ids = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_access_token, page_limit=20)
    # Find exact match
    match = None
    for result in results:
        if result['title'] == song['title']:
            artist_names = [a['name'] for a in result['artists']]
            if song['artist'] in artist_names:
                match = result
                break
    if match:
        archived_song_ids.append(match['song_id'])
        print(f"Found: {song['title']} by {song['artist']} -> song_id {match['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal archived songs found: {len(archived_song_ids)}")

# Remove the archived songs from each playlist
for playlist_id, song_ids in songs_to_remove_by_playlist.items():
    for song_id in song_ids:
        result = apis.spotify.remove_song_from_playlist(playlist_id=playlist_id, song_id=song_id, access_token=spotify_access_token)
        print(f"Removed song {song_id} from playlist {playlist_id}: {result}")

