steps.code:
# Final verification: ensure no archived songs remain in any existing playlist
archive_set = set(song_ids_to_archive)
all_playlists = apis.spotify.show_playlist_library(access_token=spotify_access_token, page_index=0, page_limit=20)
# The response might be a list or have a 'playlists' key; check structure
if isinstance(all_playlists, dict):
    playlists = all_playlists.get('playlists', [])
else:
    playlists = all_playlists

remaining = []
for pl in playlists:
    pl_id = pl['id']
    pl_data = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_access_token)
    song_ids = [song['id'] for song in pl_data['songs']]
    overlap = set(song_ids) & archive_set
    if overlap:
        remaining.append((pl_id, pl_data['title'], list(overlap)))

if remaining:
    print("WARNING: Archived songs still present in playlists:")
    for pl_id, title, songs in remaining:
        print(f"  Playlist {pl_id} ({title}): {songs}")
else:
    print("All archived songs have been removed from all existing playlists.")

# Inspect the structure of the playlists returned by show_playlist_library
print(type(all_playlists))
if isinstance(all_playlists, dict):
    print("Keys:", list(all_playlists.keys()))
    # Print first few items if there's a list
    for k, v in all_playlists.items():
        if isinstance(v, list) and v:
            print(f"First item of '{k}':", v[0])
            break
else:
    print("First item:", all_playlists[0] if all_playlists else "empty")

# Verify no archived songs remain in any existing playlist (excluding Old Songs)
archive_set = set(song_ids_to_archive)
playlist_ids = [160, 161, 162, 163, 164, 165, 166, 167]  # existing playlists

remaining = []
for pl_id in playlist_ids:
    pl_data = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_access_token)
    song_ids = [song['id'] for song in pl_data['songs']]
    overlap = set(song_ids) & archive_set
    if overlap:
        remaining.append((pl_id, pl_data['title'], list(overlap)))

if remaining:
    print("WARNING: Archived songs still present in playlists:")
    for pl_id, title, songs in remaining:
        print(f"  Playlist {pl_id} ({title}): {songs}")
else:
    print("All archived songs have been removed from all existing playlists.")

