# Check current contents of the "Old Songs" playlist to avoid duplicates
old_playlist = apis.spotify.show_playlist(playlist_id=old_songs_playlist_id, access_token=spotify_access_token)
existing_song_ids = {song['id'] for song in old_playlist['songs']}
print(f"Old Songs playlist currently has {len(existing_song_ids)} songs: {existing_song_ids}")

# Add only songs that are not already in the playlist
for song_id in song_ids_to_archive:
    if song_id not in existing_song_ids:
        result = apis.spotify.add_song_to_playlist(playlist_id=old_songs_playlist_id, song_id=song_id, access_token=spotify_access_token)
        print(f"Added song {song_id}: {result}")
    else:
        print(f"Song {song_id} already in playlist, skipping")

